def specialFilter(nums):
    def is_odd(digit):
        return digit in {1, 3, 5, 7, 9}

    def first_and_last_are_odd(num):
        num_str = str(num)
        return is_odd(int(num_str[0])) and is_odd(int(num_str[-1]))

    return len([num for num in nums if num > 10 and first_and_last_are_odd(num)])

